<script setup lang="ts">
import { computed } from 'vue'
import { choiceKey } from '../../../shared/workshop-character'
import type { WorkshopDraft } from '../../lib/homebrew-workshop'
const props=defineProps<{rules:WorkshopDraft[];level:number;modelValue:Record<string,string[]>}>()
const emit=defineEmits<{'update:modelValue':[value:Record<string,string[]>]}>()
const choices=computed(()=>props.rules.flatMap(d=>d.features.filter(f=>f.choice&&f.level<=props.level&&f.options.length).map(f=>({...f,key:choiceKey(d.id,f.id),source:d.name}))))
const retired=computed(()=>Object.entries(props.modelValue).filter(([key,values])=>values.length&&props.rules.some(r=>key.startsWith(`${r.id}:`))&&!choices.value.some(f=>f.key===key)))
function toggle(key:string,option:string,maximum:number){const selected=props.modelValue[key]??[];emit('update:modelValue',{...props.modelValue,[key]:selected.includes(option)?selected.filter(v=>v!==option):selected.length<maximum?[...selected,option]:selected})}
</script>
<template><section v-if="choices.length||retired.length" class="workshop-character-choices"><h3>Rule choices</h3><fieldset v-for="f in choices" :key="f.key"><legend>{{f.name}} · Choose {{f.choose}} <small>({{(modelValue[f.key]??[]).length}} selected)</small></legend><p>{{f.source}} · Level {{f.level}}</p><p v-if="f.description">{{f.description}}</p><label v-for="option in f.options" :key="option"><input type="checkbox" :checked="modelValue[f.key]?.includes(option)" :disabled="!modelValue[f.key]?.includes(option)&&(modelValue[f.key]?.length??0)>=f.choose" @change="toggle(f.key,option,f.choose)"/>{{option}}</label><p v-for="removed in (modelValue[f.key]??[]).filter(value=>!f.options.includes(value))" :key="removed" class="sheet-small">{{removed}} · no longer offered <button type="button" class="sheet-button sheet-small-button" @click="emit('update:modelValue',{...modelValue,[f.key]:(modelValue[f.key]??[]).filter(value=>value!==removed)})">Remove selection</button></p></fieldset><p v-for="[key,values] in retired" :key="key" class="sheet-small">Previous choice retained: {{values.join(', ')}} <button type="button" class="sheet-button sheet-small-button" @click="emit('update:modelValue',{...modelValue,[key]:[]})">Clear previous choice</button></p></section></template>
<style>.workshop-character-choices{display:grid;gap:14px}.workshop-character-choices h3{margin-bottom:4px}.workshop-character-choices fieldset{border:1px solid var(--cb-line);border-radius:8px;padding:14px;display:flex;gap:12px;flex-wrap:wrap}.workshop-character-choices legend{font-size:13px;padding:0 5px}.workshop-character-choices fieldset>p{width:100%;font-size:12px;color:var(--cb-muted);white-space:pre-wrap}.workshop-character-choices label{display:flex!important;align-items:center;gap:7px;font-size:13px}.workshop-character-choices input{width:15px!important;height:15px}</style>
